UPDATE content_section SET body_markdown = 'Antony John Blinken is an American lawyer and diplomat who served as the 71st United States secretary of state from 2021 to 2025. He previously served as deputy national security advisor from 2013 to 2015 and deputy secretary of state from 2015 to 2017 under President Barack Obama. Blinken was previously national security advisor to then-vice president Joe Biden from 2009 to 2013.', word_count = 63, last_verified_at = unixepoch() WHERE id = 'cs_antony-blinken_intro';
