UPDATE content_section SET body_markdown = 'Audrey Kathleen Hepburn was a British actress and humanitarian. Recognised as a film and fashion icon, she was ranked by the American Film Institute as the third-greatest female screen legend from the Classical Hollywood cinema. She was inducted into the International Best Dressed Hall of Fame and is one of only a few entertainers who have won competitive Academy, Emmy, Grammy and Tony Awards.', word_count = 64, last_verified_at = unixepoch() WHERE id = 'cs_audrey-hepburn_intro';
