UPDATE content_section SET body_markdown = 'Barack Hussein Obama II is an American former politician who served as the 44th president of the United States from 2009 to 2017. A member of the Democratic Party, he was the first African American to serve as president. Obama represented Illinois in the United States Senate from 2005 to 2008 and served as an Illinois state senator from 1997 to 2004.', word_count = 62, last_verified_at = unixepoch() WHERE id = 'cs_barack-obama_intro';
