UPDATE content_section SET body_markdown = 'William Bradley Pitt is an American actor and film producer. In a film career spanning more than thirty-five years, Pitt has received numerous accolades, including two Academy Awards, two British Academy Film Awards, two Golden Globe Awards, two Primetime Emmy Awards, and one Volpi Cup. His films as a leading actor have grossed over $7.5 billion worldwide.', word_count = 57, last_verified_at = unixepoch() WHERE id = 'cs_brad-pitt_intro';
