UPDATE content_section SET body_markdown = 'Calvin Coolidge was the 30th president of the United States, serving from 1923 to 1929. A Republican lawyer from Massachusetts, he served from 1921 to 1923 as the 29th vice president, under President Warren G. Harding, and from 1919 to 1921 as the 48th governor of Massachusetts. Coolidge gained a reputation as a small-government conservative, with a taciturn personality and dry sense of humor that earned him the nickname "Silent Cal".', word_count = 71, last_verified_at = unixepoch() WHERE id = 'cs_calvin-coolidge_intro';
