UPDATE content_section SET body_markdown = 'Belcalis Marlenis Almánzar, known professionally as Cardi B, is an American rapper. Born and raised in New York City, she is known for her energetic rap flow and outspoken lyrics. Since launching her music career in 2016 and releasing her two mixtapes, Cardi B has been credited for elevating the relevance of female rappers in popular music.', word_count = 57, last_verified_at = unixepoch() WHERE id = 'cs_cardi-b_intro';
