UPDATE content_section SET body_markdown = 'Carrie Marie Fisher, known professionally by her maiden name, Carrie Underwood is an American singer and songwriter. Known for her vocal range and dynamic stage presence, Underwood is recognized as a pivotal figure in 21st century country music. She has revitalized and sustained the presence of female country artists in popular culture since winning the fourth season of American Idol in 2005.', word_count = 62, last_verified_at = unixepoch() WHERE id = 'cs_carrie-underwood_intro';
