UPDATE content_section SET body_markdown = 'Sir Charles Spencer Chaplin Jr. was an English comic actor, filmmaker, singer, film editor and composer who rose to fame in the era of silent film. He became a worldwide icon through his screen persona, the Tramp, and is considered one of the film industry''s most important figures. His career spanned more than 75 years, from his childhood in the Victorian era until a year before his death in 1977.', word_count = 70, last_verified_at = unixepoch() WHERE id = 'cs_charlie-chaplin_intro';
