UPDATE content_section SET body_markdown = 'Richard Bruce Cheney was an American politician and businessman who served as the 46th vice president of the United States under President George W. Bush from 2001 to 2009. Considered to be the main architect of the Iraq War, Cheney has been called by analysts and historians as the most powerful vice president in the history of the United States.', word_count = 60, last_verified_at = unixepoch() WHERE id = 'cs_dick-cheney_intro';
