UPDATE content_section SET body_markdown = 'Edward Kennedy "Duke" Ellington was an American jazz pianist, composer, and leader of his eponymous jazz orchestra from 1924 through the rest of his life. Music critic Ralph J. Gleason called him "America''s most important composer".', word_count = 36, last_verified_at = unixepoch() WHERE id = 'cs_duke-ellington_intro';
