UPDATE content_section SET body_markdown = 'Edgar Allan Poe was an American writer, poet, editor, and literary critic who is best known for his poetry and short stories, particularly his tales involving mystery and the macabre. He is widely regarded as one of the central figures of Romanticism and Gothic fiction in the United States and of early American literature.', word_count = 54, last_verified_at = unixepoch() WHERE id = 'cs_edgar-allan-poe_intro';
