UPDATE content_section SET body_markdown = 'Elena Kagan is an American lawyer who serves as an associate justice of the Supreme Court of the United States. She was appointed in 2010 by President Barack Obama and is the fourth woman to serve on the Court.', word_count = 39, last_verified_at = unixepoch() WHERE id = 'cs_elena-kagan_intro';
