UPDATE content_section SET body_markdown = 'Emily Elizabeth Dickinson was an American poet. Largely unpublished and unknown during her lifetime, her work is now widely regarded as canonical. The Poetry Foundation describes her as having "created in her writing a distinctively elliptical language for expressing what was possible but not yet realized."', word_count = 46, last_verified_at = unixepoch() WHERE id = 'cs_emily-dickinson_intro';
