UPDATE content_section SET body_markdown = 'Emily Jean "Emma" Stone is an American actress and film producer. Her accolades include two Academy Awards, two BAFTA Awards, two Golden Globe Awards and a Volpi Cup as well as a nomination for a Primetime Emmy Award. In 2017, she was the world''s highest-paid actress and named by Time magazine as one of the 100 most influential people in the world.', word_count = 62, last_verified_at = unixepoch() WHERE id = 'cs_emma-stone_intro';
