UPDATE content_section SET body_markdown = 'George B. McClellan (1826–1885) was an American Civil War military leader, presidential candidate and Governor of New Jersey.', word_count = 18, last_verified_at = unixepoch() WHERE id = 'cs_george-mcclellan_intro';
UPDATE content_section SET body_markdown = 'George Walker Bush is an American former politician, businessman, and former United States Air Force officer who was the 43rd president of the United States, serving from 2001 to 2009. A member of the Republican Party, he served as the governor of Texas from 1995 to 2000. He is the eldest son of George H. W. Bush, the 41st president of the United States.', word_count = 64, last_verified_at = unixepoch() WHERE id = 'cs_george-w-bush_intro';
