UPDATE content_section SET body_markdown = 'Gerald Rudolph Ford Jr. was the 38th president of the United States, serving from 1974 to 1977. He assumed the presidency after the resignation of Richard Nixon, under whom he served as the 40th vice president from 1973 to 1974, after the resignation of Spiro Agnew. A member of the Republican Party, Ford previously served in the United States House of Representatives from 1949 to 1973.', word_count = 66, last_verified_at = unixepoch() WHERE id = 'cs_gerald-ford_intro';
