UPDATE content_section SET body_markdown = 'Henry David Thoreau was an American naturalist, essayist, poet, and philosopher. A leading transcendentalist, he is best known for his book Walden, a reflection upon simple living in natural surroundings, and his essay "Civil Disobedience", an argument in favor of citizen disobedience against an unjust state.', word_count = 46, last_verified_at = unixepoch() WHERE id = 'cs_henry-david-thoreau_intro';
