UPDATE content_section SET body_markdown = 'Herbert Raymond McMaster is a retired United States Army lieutenant general who served as the 25th United States National Security Advisor from 2017 to 2018. He is also known for his roles in the Gulf War, Operation Enduring Freedom, and Operation Iraqi Freedom.', word_count = 43, last_verified_at = unixepoch() WHERE id = 'cs_hr-mcmaster_intro';
