UPDATE content_section SET body_markdown = 'John Craig Venter was an American scientist, businessman, and genomics researcher. He is known for having led one of the first draft sequences of the human genome and led the first team to transfect a cell with a synthetic chromosome. Venter founded Celera Genomics, the Institute for Genomic Research (TIGR) and the J. Craig Venter Institute (JCVI). He was the co-founder of Human Longevity Inc., and Synthetic Genomics.', word_count = 68, last_verified_at = unixepoch() WHERE id = 'cs_j-craig-venter_intro';
