UPDATE content_section SET body_markdown = 'Jack William Nicklaus, nicknamed "the Golden Bear", is an American retired professional golfer and golf course designer. He is widely considered to be one of the greatest golfers of all time. He won 117 professional tournaments in his career, including a record 18 major championships. He is an inductee of the World Golf Hall of Fame.', word_count = 56, last_verified_at = unixepoch() WHERE id = 'cs_jack-nicklaus_intro';
