UPDATE content_section SET body_markdown = 'James Madison was a Founding Father and the fourth president of the United States from 1809 to 1817. Before his presidency, Madison was a statesman and diplomat. Madison was popularly acclaimed as the "Father of the Constitution" for his pivotal role in drafting and promoting the Constitution of the United States and the Bill of Rights.', word_count = 56, last_verified_at = unixepoch() WHERE id = 'cs_james-madison_intro';
