UPDATE content_section SET body_markdown = 'Jeffrey Preston Bezos is an American businessman, and the founder, executive chairman, and former president and CEO of Amazon, the world''s largest e-commerce and cloud computing company. According to the Bloomberg Billionaires Index and Forbes, he was the world''s wealthiest person from 2017 to 2021, and in 2026 his net worth was approximately US$284 billion.', word_count = 55, last_verified_at = unixepoch() WHERE id = 'cs_jeff-bezos_intro';
