UPDATE content_section SET body_markdown = 'Jerry Laymon Falwell was an American Baptist pastor, televangelist, and politically conservative activist. He was the founding pastor of the Thomas Road Baptist Church, a megachurch in Lynchburg, Virginia. He founded Lynchburg Christian Academy, later renamed Liberty Christian Academy, in 1967, founded Liberty University in 1971, and co-founded the Moral Majority in 1979.', word_count = 53, last_verified_at = unixepoch() WHERE id = 'cs_jerry-falwell_intro';
