UPDATE content_section SET body_markdown = 'Jimmy Donal Wales is an American and British internet entrepreneur and former financial trader. He is best known for co-founding Wikipedia, a nonprofit free encyclopedia, and Fandom, a for-profit wiki hosting service. He has also worked on Bomis, Nupedia, WikiTribune, and Trust Café.', word_count = 43, last_verified_at = unixepoch() WHERE id = 'cs_jimmy-wales_intro';
