UPDATE content_section SET body_markdown = 'Joan Mitchell was an American artist who worked primarily in painting and printmaking, and also used pastel and made other works on paper. She was an active participant in the New York School of artists in the 1950s. A native of Chicago, she is associated with the American abstract expressionist movement, even though she lived in France for much of her career.', word_count = 62, last_verified_at = unixepoch() WHERE id = 'cs_joan-mitchell_intro';
