UPDATE content_section SET body_markdown = 'Joseph Robinette Biden Jr. is an American former politician who was the 46th president of the United States from 2021 to 2025. A member of the Democratic Party, he represented Delaware in the United States Senate from 1973 to 2009 and also served as the 47th vice president under President Barack Obama from 2009 to 2017.', word_count = 56, last_verified_at = unixepoch() WHERE id = 'cs_joe-biden_intro';
