UPDATE content_section SET body_markdown = 'Joseph Paul DiMaggio, nicknamed "Joltin'' Joe", "the Yankee Clipper" and "Joe D.", was an American professional baseball center fielder who played his entire 13-year career in Major League Baseball (MLB) for the New York Yankees. Born to Italian immigrants in California, he is considered to be one of the greatest baseball players of all time and set the record for the longest hitting streak.', word_count = 64, last_verified_at = unixepoch() WHERE id = 'cs_joe-dimaggio_intro';
