UPDATE content_section SET body_markdown = 'John Cabell Breckinridge was an American politician who served as the 14th vice president of the United States, with President James Buchanan, from 1857 to 1861, and as a general in the Confederate Army during the American Civil War. Assuming office at the age of 36, Breckinridge is the youngest vice president in U.S. history. He was also the Southern Democratic candidate in the 1860 presidential election, losing to Republican candidate Abraham Lincoln.', word_count = 73, last_verified_at = unixepoch() WHERE id = 'cs_john-c-breckinridge_intro';
