UPDATE content_section SET body_markdown = 'John Herschel Glenn Jr. was an American Marine Corps aviator, astronaut, businessman, and politician. He was the third American in space and the first to orbit the Earth, circling it three times in 1962. Following his retirement from NASA, he served from 1974 to 1999 as a U.S. senator from Ohio. In 1998, he flew into space again at the age of 77.', word_count = 63, last_verified_at = unixepoch() WHERE id = 'cs_john-glenn_intro';
