UPDATE content_section SET body_markdown = 'John Forbes Kerry is an American attorney, politician, diplomat, and former naval officer who served as the 68th United States secretary of state from 2013 to 2017 in the administration of President Barack Obama. A member of the Democratic Party, he previously represented Massachusetts in the United States Senate from 1985 to 2013 and later served as the first U.S. special presidential envoy for climate from 2021 to 2024. Kerry was the Democratic presidential nominee in the 2004 presidential election.', word_count = 80, last_verified_at = unixepoch() WHERE id = 'cs_john-kerry_intro';
