UPDATE content_section SET body_markdown = 'Katherine Anne Couric is an American journalist and presenter. She is founder of Katie Couric Media, a multimedia news and production company. She also publishes a daily newsletter, Wake Up Call. Since 2016, she has hosted the podcast Next Question with Katie Couric.', word_count = 43, last_verified_at = unixepoch() WHERE id = 'cs_katie-couric_intro';
