UPDATE content_section SET body_markdown = 'Kendrick Lamar Duckworth is an American rapper and songwriter. Rooted in West Coast hip-hop, his music features conscious, introspective lyrics, with political criticism and social commentary concerning African-American culture. Music journalists have listed Lamar among the greatest rappers of all time. In 2018, he became the first musician outside of the classical and jazz genres to receive the Pulitzer Prize for Music.', word_count = 62, last_verified_at = unixepoch() WHERE id = 'cs_kendrick-lamar_intro';
