UPDATE content_section SET body_markdown = 'Claudia Alta "Lady Bird" Johnson was the first lady of the United States from 1963 to 1969 as the wife of Lyndon B. Johnson, the 36th president of the United States. She had previously been the second lady of the United States from 1961 to 1963, when her husband was vice president under President John F. Kennedy.', word_count = 57, last_verified_at = unixepoch() WHERE id = 'cs_lady-bird-johnson_intro';
