UPDATE content_section SET body_markdown = 'Larry Joe Bird is an American former professional basketball player, coach, and executive in the National Basketball Association (NBA). Nicknamed "the Hick from French Lick" and "Larry Legend", Bird is widely regarded as one of the greatest basketball players of all time. He is the only person in NBA history to be named Rookie of the Year, Most Valuable Player, Finals MVP, All-Star MVP, Coach of the Year, and Executive of the Year.', word_count = 73, last_verified_at = unixepoch() WHERE id = 'cs_larry-bird_intro';
