UPDATE content_section SET body_markdown = 'LeBron Raymone James Sr. is an American professional basketball player for the Philadelphia 76ers of the National Basketball Association (NBA). Nicknamed "King James", he is the NBA''s all-time leading scorer and has won four NBA championships from 10 NBA Finals appearances, including eight consecutive appearances between 2011 and 2018. He has won three Olympic gold medals as a member of the U.S. national team, and is widely considered to be one of the greatest basketball players of all time and one of the greatest athletes in modern history.', word_count = 88, last_verified_at = unixepoch() WHERE id = 'cs_lebron-james_intro';
