UPDATE content_section SET body_markdown = 'Leonardo Wilhelm DiCaprio is an American actor and film producer. Known for his work in biographical and period films, he is the recipient of numerous accolades, including an Academy Award, an Actor Award, a BAFTA Award, an Emmy Award, a Silver Bear and three Golden Globes. His films as a leading actor have grossed $7 billion worldwide, and he has been placed eight times in annual rankings of the world''s highest-paid actors.', word_count = 72, last_verified_at = unixepoch() WHERE id = 'cs_leonardo-dicaprio_intro';
