UPDATE content_section SET body_markdown = 'Linus Benedict Torvalds is a Finnish and American software engineer who is the creator and lead developer of the Linux kernel since 1991. He also created the distributed version control system Git.', word_count = 32, last_verified_at = unixepoch() WHERE id = 'cs_linus-torvalds_intro';
