UPDATE content_section SET body_markdown = 'Melissa Viviane Jefferson, known professionally as Lizzo, is an American singer, rapper, songwriter, and actress. Born in Detroit, Michigan, she moved to Houston, Texas, with her family at the age of 10. After college, she moved to Minneapolis, Minnesota, where she began her recording career in hip-hop. Lizzo released two studio albums, Lizzobangers (2013) and Big Grrrl Small World (2015).', word_count = 60, last_verified_at = unixepoch() WHERE id = 'cs_lizzo_intro';
