UPDATE content_section SET body_markdown = 'Eliza Rosanna Gilbert, better known by the stage name Lola Montez, was an Irish dancer and actress who became famous as a Spanish dancer, courtesan, and mistress of King Ludwig I of Bavaria, who made her Gräfin (Countess) von Landsfeld. At the start of the Revolutions of 1848 in the German states, she was forced to flee. She proceeded to the United States via Austria, Switzerland, France and London, to return to her work as an entertainer and lecturer.', word_count = 79, last_verified_at = unixepoch() WHERE id = 'cs_lola-montez_intro';
